use vstd::prelude::*;
use vstd::slice::*;

verus! {

spec fn is_last_maximum(v: &[i32], i: int) -> bool {
    &&& 0 <= i < v.len()
    &&& forall|j: int| 0 <= j < v.len() ==> v[j] <= v[i]
    &&& forall|k: int| i < k < v.len() ==> v[k] < v[i]
}

fn mlast_maximum(v: &[i32]) -> (i: usize)
    requires
        v.len() > 0,
    ensures
        is_last_maximum(v, i as int),
{
    let mut max_val = v[0];
    let mut last_max_idx: usize = 0;
    let mut current_idx: usize = 1;
    
    while current_idx < v.len()
        invariant
            current_idx <= v.len(),
            0 <= last_max_idx < v.len(),
            // max_val equals the value at last_max_idx
            max_val == v[last_max_idx],
            // max_val is at least as large as all elements in [0, current_idx)
            forall|j: int| 0 <= j < current_idx ==> v[j] <= max_val,
            // No element equal to max_val appears after last_max_idx in [0, current_idx)
            forall|k: int| last_max_idx < k < current_idx ==> v[k] < max_val,
        decreases v.len() - current_idx,
    {
        let elem = v[current_idx];
        
        if elem > max_val {
            // Found a new maximum
            max_val = elem;
            last_max_idx = current_idx;
        } else if elem == max_val {
            // Found another occurrence of current maximum
            last_max_idx = current_idx;
        }
        // If elem < max_val, we don't need to update anything
        
        current_idx = current_idx + 1;
    }
    
    last_max_idx
}

} // verus!

fn main() {
    // Test cases
    let arr1 = [1, 2, 3, 2, 1];
    let idx1 = mlast_maximum(&arr1);
    assert(idx1 == 2);
    
    let arr2 = [3, 1, 3, 2, 3];
    let idx2 = mlast_maximum(&arr2);
    assert(idx2 == 4);
    
    let arr3 = [5];
    let idx3 = mlast_maximum(&arr3);
    assert(idx3 == 0);
}